// Target audience: developers. Generated bytes only; validates the encrypted intake protocol.
import CryptoKit
import Foundation

@main struct VaultInboxChecks {
    static func main() async throws {
        let root = FileManager.default.temporaryDirectory.appendingPathComponent("vault-inbox-check-" + UUID().uuidString, isDirectory: true)
        try FileManager.default.createDirectory(at: root, withIntermediateDirectories: true)
        defer { try? FileManager.default.removeItem(at: root) }
        let source = root.appendingPathComponent("source.png")
        let data = Data((0..<(1_200_000)).map { UInt8($0 % 251) })
        try data.write(to: source)
        let queue = root.appendingPathComponent("queue")
        let vaultKey = SymmetricKey(data: Data(repeating: 42, count: 32))
        let privateKey = try GalleryVaultInbox.privateKey(vaultKey: vaultKey)
        try GalleryVaultInbox.publishPublicKey(privateKey.publicKey.rawRepresentation, in: queue)
        let another = try GalleryVaultInbox.privateKey(vaultKey: vaultKey)
        precondition(privateKey.publicKey.rawRepresentation == another.publicKey.rawRepresentation)
        let input = GalleryVaultInbox.Input(url: source, filename: "source.png", typeIdentifier: "public.png")
        _ = try await GalleryVaultInbox.save(items: [input], in: queue)
        let files = try GalleryVaultInbox.batchFiles(in: queue).flatMap { $0 }
        precondition(files.count == 1)
        let ciphertext = try Data(contentsOf: files[0])
        precondition(!ciphertext.contains(data.prefix(64)))
        var info: GalleryVaultInbox.Metadata?
        var decoded = Data()
        try GalleryVaultInbox.read(files[0], privateKey: { privateKey }, metadata: { info = $0 }, append: { decoded.append($0) })
        precondition(decoded == data && info?.filename == "source.png")
        let original = try Data(contentsOf: source)
        precondition(original == data)
        let other = Curve25519.KeyAgreement.PrivateKey()
        do {
            try GalleryVaultInbox.publishPublicKey(other.publicKey.rawRepresentation, in: queue)
            fatalError("different key replaced a live queue")
        } catch GalleryVaultInbox.InboxError.incompatibleKey {}
        func rejected(_ file: URL, key: Curve25519.KeyAgreement.PrivateKey) -> Bool {
            do { try GalleryVaultInbox.read(file, privateKey: { key }, metadata: { _ in }, append: { _ in }); return false }
            catch { return true }
        }
        precondition(rejected(files[0], key: other))
        let corrupted = files[0].deletingLastPathComponent().appendingPathComponent("corrupt", isDirectory: true)
        try FileManager.default.createDirectory(at: corrupted, withIntermediateDirectories: true)
        let corruptedFile = corrupted.appendingPathComponent(files[0].lastPathComponent)
        var changed = ciphertext
        changed[changed.count - 9] ^= 0x01
        try changed.write(to: corruptedFile)
        precondition(rejected(corruptedFile, key: privateKey))
        try ciphertext.dropLast(5).write(to: corruptedFile)
        precondition(rejected(corruptedFile, key: privateKey))
        try (ciphertext + Data([0])).write(to: corruptedFile)
        precondition(rejected(corruptedFile, key: privateKey))
        print("PASS encrypted queue, exact bytes, stable key, key rotation fence, tamper, truncation, trailing bytes")
    }
}
